CREATE TABLE IF NOT EXISTS `work_project` (`created_at` BIGINT NOT NULL, `id` BIGINT NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `owner_user` BIGINT NOT NULL, `status` ENUM('active', 'archived') NOT NULL DEFAULT 'active', `updated_at` BIGINT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_work_project_owner_name` (`owner_user`, `name`), UNIQUE KEY `uk_work_project_id_owner` (`id`, `owner_user`), KEY `idx_work_project_owner_status_name` (`owner_user`, `status`, `name`), CONSTRAINT `fk_work_project_owner` FOREIGN KEY (`owner_user`) REFERENCES `users` (`id`) ON UPDATE RESTRICT ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
